function show(html,buttons=[]){card.innerHTML=html+(buttons.length?'<div class="actions">'+buttons.map((b,i)=>`<button class="pixel-btn ${b.secondary?'secondary':''}" data-action="${i}">${b.label}</button>`).join('')+'</div>':'');overlay.classList.remove('closed');card.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>buttons[+el.dataset.action].fn())}function hide(){overlay.classList.add('closed')}function toast(s){const e=$('#toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
function hasSavedCase(){return !!(state.started||state.scene>0||state.clues?.length||state.letter||state.portalReady||Number.isFinite(state.x)||Number.isFinite(state.y))}
function startNewCase(){state={scene:0,clues:[],started:true};scene=0;x=targetX=135;y=targetY=400;endingPhase='';endingStarted=false;hide();save();say('ASMITA','Hmm… what’s this? A glowing envelope in the middle of the street?')}
function resumeCase(){scene=Math.max(0,Math.min(8,Number(state.scene)||0));x=targetX=Number.isFinite(state.x)?state.x:135;y=targetY=Number.isFinite(state.y)?state.y:400;updateHud();hide();if(scene>=8&&state.letter){finalTogether();return}if(scene>=5&&scene<=7){caveReveal();return}if(scene===4&&allEvidence()&&!state.portalReady){finalPuzzle();return}save();say('ASMITA',scene===0?'Let’s pick up the investigation where I left off.':scene===4&&state.portalReady?'The portal is still open. One last step, then I’ll find out who’s waiting.':'The clues are saved. I know where I left off.')}
function opening(){scene=Math.max(0,Math.min(8,Number(state.scene)||0));updateHud();const saved=hasSavedCase();show(`<div class="title-hero"><div class="title-hero-art">${portraitMarkup('ASMITA')}</div><div class="title-hero-copy"><div class="eyebrow">AN INTERACTIVE 2D STORY · MADE FOR ASMITA</div><h1>THE LAST<br>CLUE</h1><p class="subtitle">Some mysteries aren't meant to be solved.<br>Some are meant to be felt.</p><p>${saved?'Your case is saved on this device. Continue where you left off, or begin a new investigation.':'One detective. Four clues. One last surprise waiting beyond the town.'}</p></div></div>`,saved?[{label:'CONTINUE INVESTIGATION',fn:resumeCase},{label:'START A NEW CASE',secondary:true,fn:()=>show(`<div class="eyebrow">START OVER?</div><h2>Begin a new investigation?</h2><p>Your current case is saved. Starting a new one will replace it on this device.</p>`,[{label:'START NEW CASE',fn:startNewCase},{label:'KEEP MY CASE',secondary:true,fn:opening}])}]:[{label:'START INVESTIGATION',fn:startNewCase}]);}
function intro(){hide();scene=state.scene||0;if(scene===8&&state.letter){endCard();return}if(scene===6){if(state.letter)finalTogether();else caveReveal();return}if(scene===4&&allEvidence()&&!state.portalReady){finalPuzzle();return}save();const lines={0:'The message is waiting by the streetlight. Let’s see where it leads.',1:'Back at the old library. I should search for the next clue.',2:'The park photograph is still on my list. The trail continues.',3:'The old station is quiet. I’m close to the last clue.',4:'The rooftop key points somewhere beyond town. The cave must be nearby.'};say('ASM​​ITA',lines[scene]||'Let’s pick up the investigation where I left off.')}function say(who,text,done){cinematic=true;$('#speaker').textContent=who;$('#line').textContent=text;$('#dialogue').classList.remove('hidden');dialogues=[done||(()=>{$('#dialogue').classList.add('hidden');cinematic=false})];}function next(){if(!dialogues.length)return;const f=dialogues.shift();$('#dialogue').classList.add('hidden');cinematic=false;f()}
